/** Replaces every var(--token) with its :root value, recursively. */
function resolveVars(value: string): string {
  let current = value;
  for (let i = 0; i < 8 && /var\(--[\w-]+\)/.test(current); i += 1) {
    current = current.replace(/var\((--[\w-]+)\)/g, (_all, name: string) => rootToken(name));
